/**
 * Juggernaut XL (SDXL, CreativeML Open RAIL++-M: outputs are ours) on the AI Horde — a free, volunteer GPU network; anonymous
 * key, no account, no money. Each creature gets TAKES seeds; the art director picks the best one (assets/art-src/picks.json).
 */
const HORDE = 'https://aihorde.net/api/v2';
const H = { 'Content-Type': 'application/json', apikey: '0000000000', 'Client-Agent': 'junglee-studio:7:shv27' };
const NEG = 'text, watermark, signature, frame, border, blurry, cartoon, anime, deformed, extra limbs, extra heads, cropped';
async function flux(prompt, seed, w, h) {
  const r = await fetch(`${HORDE}/generate/async`, {
    method: 'POST',
    headers: H,
    signal: AbortSignal.timeout(60000),
    body: JSON.stringify({
      prompt: `${prompt} ### ${NEG}`,
      models: [process.env.MODEL ?? 'Juggernaut XL'],
      r2: true,
      shared: false,
      params: { width: w, height: h, steps: 30, cfg_scale: 6, sampler_name: 'k_dpmpp_2m', karras: true, n: 1, seed: String(seed) },
    }),
  });
  const j = await r.json();
  if (!j.id) throw new Error(`horde: ${JSON.stringify(j).slice(0, 160)}`);
  const t0 = Date.now();
  for (;;) {
    await new Promise((ok) => setTimeout(ok, 6000));
    const c = await (await fetch(`${HORDE}/generate/check/${j.id}`, { signal: AbortSignal.timeout(30000) })).json();
    if (c.done) break;
    if (c.faulted || Date.now() - t0 > 15 * 60000) throw new Error('horde faulted/timeout');
  }
  const st = await (await fetch(`${HORDE}/generate/status/${j.id}`, { signal: AbortSignal.timeout(30000) })).json();
  const img = st.generations?.[0]?.img;
  if (!img) throw new Error('horde: no image');
  return Buffer.from(await (await fetch(img, { signal: AbortSignal.timeout(60000) })).arrayBuffer());
}

async function cutout(buf) {
  const b64 = `data:image/webp;base64,${buf.toString('base64')}`;
  const r = await fetch(`${CUT}/gradio_api/call/png`, {
    signal: AbortSignal.timeout(60000),
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: [{ url: b64, meta: { _type: 'gradio.FileData' } }] }),
  });
  const { event_id } = await r.json();
  const s = await (await fetch(`${CUT}/gradio_api/call/png/${event_id}`, { signal: AbortSignal.timeout(180000) })).text();
  const url = s.match(/"url": "([^"]+)"/)?.[1];
  if (!url) throw new Error(`cutout failed: ${s.slice(0, 200)}`);
  return Buffer.from(await (await fetch(url, { signal: AbortSignal.timeout(60000) })).arrayBuffer());
}

async function retry(fn, n = 4) {
  for (let i = 0; ; i++) {
    try {
      return await fn();
    } catch (e) {
      if (i >= n) throw e;
      await new Promise((ok) => setTimeout(ok, 4000 * (i + 1)));
    }
  }
}

const only = new Set(process.argv.slice(2));
const jobs = [];
let seed = 100;
for (const [id, d] of Object.entries(CREATURES))
  jobs.push({ id, prompt: `Full body painting of ${d}, ${STYLE}`, seed: seed++, w: 768, h: 1024, cut: true });
for (const [id, d] of Object.entries(HEROES))
  jobs.push({
    id: `hero-${id}`,
    prompt: `Full body painting of ${d}, adventure movie character art, ${STYLE}`,
    seed: seed++,
    w: 768,
    h: 1024,
    cut: true,
  });
for (const [id, [d, s, w, h]] of Object.entries(SCENES))
  jobs.push({ id, prompt: `${d}, ${SCENE}`, seed: s, w, h, cut: false });

const TAKES = Number(process.env.TAKES ?? 2);

/** Raw takes only; picking (assets/art-src/picks.json) and cutting (scripts/cut-art.py) come after the art director's review. */
async function work(j, take) {
  if (only.size && !only.has(j.id)) return;
  const raw = path.join(SRC, `${j.id}-${take}.webp`);
  if (fs.existsSync(raw)) return;
  fs.writeFileSync(raw, await retry(() => flux(j.prompt, j.seed + take * 1000, j.w, j.h), 2));
  console.log('take', j.id, take, new Date().toLocaleTimeString());
}

const queue = jobs.flatMap((j) => Array.from({ length: j.cut ? TAKES : 1 }, (_, t) => ({ j, t })));
await Promise.all(
  Array.from({ length: Number(process.env.JOBS ?? 4) }, async () => {
    while (queue.length) {
      const { j, t } = queue.shift();
      try {
        await work(j, t);
      } catch (e) {
        console.error('FAILED', j.id, t, e.message);
      }
    }
  }),
);
console.log('all done');
